import{_ as l,a0 as o,w as p,s as r,ao as d,I as i,x as a,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"全面介绍 Linux 权限 | LCTT x X-CMD","titleTemplate":false,"description":"全面介绍 Linux 权限 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"全面介绍 Linux 权限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"全面介绍 Linux 权限 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20190801 Linux permissions 101","title":"全面介绍 Linux 权限","tag":"201911","desc":""},"relativePath":"201911/20190801 Linux permissions 101.md","filePath":"[post].md"}'),c={name:"201911/20190801 Linux permissions 101.md"};function h(g,s,k,u,b,f){const e=o("Link");return p(),r("div",null,[s[28]||(s[28]=d(`<h1 id="全面介绍-linux-权限" tabindex="-1">全面介绍 Linux 权限 <a class="header-anchor" href="#全面介绍-linux-权限" aria-label="Permalink to “全面介绍 Linux 权限”">​</a></h1><blockquote><p>知道如何控制用户对文件的访问是一项基本的系统管理技能。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/08/233101y043rn4ua00r3lqn.jpg" alt=""></p><p>了解 Linux 权限以及如何控制哪些用户可以访问文件是系统管理的一项基本技能。</p><p>本文将介绍标准 Linux 文件系统权限，并进一步研究特殊权限，以及使用 <code>umask</code> 来解释默认权限作为文章的结束。</p><h3 id="理解-ls-命令的输出" tabindex="-1">理解 ls 命令的输出 <a class="header-anchor" href="#理解-ls-命令的输出" aria-label="Permalink to “理解 ls 命令的输出”">​</a></h3><p>在讨论如何修改权限之前，我们需要知道如何查看权限。通过 <code>ls</code> 命令的长列表参数（<code>-l</code>）为我们提供了有关文件的许多信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lAh</span></span>
<span class="line"><span>total 20K</span></span>
<span class="line"><span>-rwxr-xr--+ 1 root root    0 Mar  4 19:39 file1</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root    0 Mar  4 19:39 file10</span></span>
<span class="line"><span>-rwxrwxr--+ 1 root root    0 Mar  4 19:39 file2</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root    0 Mar  4 19:39 file8</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root    0 Mar  4 19:39 file9</span></span>
<span class="line"><span>drwxrwxrwx. 2 root root 4.0K Mar  4 20:04 testdir</span></span></code></pre></div><p>为了理解这些是什么意思，让我们将关于权限的输出分解为各个部分。单独理解每个部分会更容易。</p><p>让我们看看在上面的输出中的最后一行的每个组件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwxrwx. 2 root root 4.0K Mar  4 20:04 testdir</span></span></code></pre></div><div class="table-wrap"><table><thead><tr><th>第 1 节</th><th>第 2 节</th><th>第 3 节</th><th>第 4 节</th><th>第 5 节</th><th>第 6 节</th><th>第 7 节</th></tr></thead><tbody><tr><td><code>d</code></td><td><code>rwx</code></td><td><code>rwx</code></td><td><code>rwx</code></td><td><code>.</code></td><td><code>root</code></td><td><code>root</code></td></tr></tbody></table></div><p>第 1 节（左侧）显示文件的类型。</p><div class="table-wrap"><table><thead><tr><th>符号</th><th>类型</th></tr></thead><tbody><tr><td><code>d</code></td><td>目录</td></tr><tr><td><code>-</code></td><td>常规文件</td></tr><tr><td><code>l</code></td><td>软链接</td></tr></tbody></table></div>`,14)),i("p",null,[s[1]||(s[1]=i("code",null,"ls",-1)),s[2]||(s[2]=a(" 的 ",-1)),n(e,{href:"https://www.gnu.org/software/texinfo/manual/info-stnd/info-stnd.html"},{default:t(()=>[...s[0]||(s[0]=[a("info 页面",-1)])]),_:1}),s[3]||(s[3]=a("完整列出了不同的文件类型。",-1))]),s[29]||(s[29]=d(`<p>每个文件都有三种访问方式：</p><ul><li>属主</li><li>组</li><li>所有其他人    第 2、3 和 4 节涉及用户（属主）、组和“其他用户”权限。每个部分都可以包含 <code>r</code>（读取）、<code>w</code>（写入）和 <code>x</code>（执行）权限的组合。</li></ul><p>每个权限还分配了一个数值，这在以八进制表示形式讨论权限时很重要。</p><div class="table-wrap"><table><thead><tr><th>权限</th><th>八进制值</th></tr></thead><tbody><tr><td><code>r</code></td><td>4</td></tr><tr><td><code>w</code></td><td>2</td></tr><tr><td><code>x</code></td><td>1</td></tr></tbody></table></div><p>第 5 节描述了其他替代访问方法，例如 SELinux 或文件访问控制列表（FACL）。</p><div class="table-wrap"><table><thead><tr><th>访问方法</th><th>字符</th></tr></thead><tbody><tr><td>没有其它访问方法</td><td><code>-</code></td></tr><tr><td>SELinux</td><td><code>.</code></td></tr><tr><td>FACL</td><td><code>+</code></td></tr><tr><td>各种方法的组合</td><td><code>+</code></td></tr></tbody></table></div><p>第 6 节和第 7 节分别是属主和组的名称。</p><h3 id="使用-chown-和-chmod" tabindex="-1">使用 chown 和 chmod <a class="header-anchor" href="#使用-chown-和-chmod" aria-label="Permalink to “使用 chown 和 chmod”">​</a></h3><h4 id="chown-命令" tabindex="-1">chown 命令 <a class="header-anchor" href="#chown-命令" aria-label="Permalink to “chown 命令”">​</a></h4><p><code>chown</code>（更改所有权）命令用于更改文件的用户和组的所有权。</p><p>要将文件 <code>foo</code> 的用户和组的所有权更改为 <code>root</code>，我们可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown root:root foo</span></span>
<span class="line"><span>$ chown root: foo</span></span></code></pre></div><p>在用户名后跟冒号（<code>:</code>）运行该命令将同时设置用户和组所有权。</p><p>要仅将文件 <code>foo</code> 的用户所有权设置为 <code>root</code> 用户，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown root foo</span></span></code></pre></div><p>要仅更改文件 <code>foo</code> 的组所有权，请在组之前加冒号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown :root foo</span></span></code></pre></div><h4 id="chmod-命令" tabindex="-1">chmod 命令 <a class="header-anchor" href="#chmod-命令" aria-label="Permalink to “chmod 命令”">​</a></h4><p><code>chmod</code>（更改模式）命令控制属主、组以及既不是属主也不属于与文件关联的组的所有其他用户的文件许可权。</p><p><code>chmod</code> 命令可以以八进制（例如 <code>755</code>、<code>644</code> 等）和符号（例如 <code>u+rwx</code>、<code>g-rwx</code>、<code>o=rw</code>）格式设置权限。</p><p>八进制表示法将 4 个“点”分配给“读取”，将 2 个“点”分配给“写入”，将 1 个点分配给“执行”。如果要给用户（属主）分配“读取”权限，则将 4 分配给第一个插槽，但是如果要添加“写入”权限，则必须添加 2。如果要添加“执行”，则要添加 1。我们对每种权限类型执行此操作：属主、组和其他。</p><p>例如，如果我们想将“读取”、“写入”和“执行”分配给文件的属主，但仅将“读取”和“执行”分配给组成员和所有其他用户，则我们应使用 <code>755</code>（八进制格式）。这是属主的所有权限位（<code>4+2+1</code>），但组和其他权限的所有权限位只有 <code>4</code> 和 <code>1</code>（<code>4+1</code>）。</p><blockquote><p>细分为：4+2+1=7，4+1=5 和 4+1=5。</p></blockquote><p>如果我们想将“读取”和“写入”分配给文件的属主，而只将“读取”分配给组的成员和所有其他用户，则可以如下使用 <code>chmod</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 644 foo_file</span></span></code></pre></div><p>在下面的示例中，我们在不同的分组中使用符号表示法。注意字母 <code>u</code>、<code>g</code> 和 <code>o</code> 分别代表“用户”（属主）、“组”和“其他”。我们将 <code>u</code>、<code>g</code> 和 <code>o</code> 与 <code>+</code>、<code>-</code> 或 <code>=</code> 结合使用来添加、删除或设置权限位。</p><p>要将“执行”位添加到所有权权限集中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod u+x foo_file</span></span></code></pre></div><p>要从组成员中删除“读取”、“写入”和“执行”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod g-rwx foo_file</span></span></code></pre></div><p>要将所有其他用户的所有权设置为“读取”和“写入”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod o=rw</span></span></code></pre></div><h3 id="特殊位-设置-uid、设置-gid-和粘滞位" tabindex="-1">特殊位：设置 UID、设置 GID 和粘滞位 <a class="header-anchor" href="#特殊位-设置-uid、设置-gid-和粘滞位" aria-label="Permalink to “特殊位：设置 UID、设置 GID 和粘滞位”">​</a></h3><p>除了标准权限外，还有一些特殊的权限位，它们具有一些别的用处。</p><h4 id="设置用户-id-suid" tabindex="-1">设置用户 ID（suid） <a class="header-anchor" href="#设置用户-id-suid" aria-label="Permalink to “设置用户 ID（suid）”">​</a></h4>`,35)),i("p",null,[s[5]||(s[5]=a("当在文件上设置 ",-1)),s[6]||(s[6]=i("code",null,"suid",-1)),s[7]||(s[7]=a(" 时，将以文件的属主的身份而不是运行该文件的用户身份执行操作。一个",-1)),n(e,{href:"https://www.theurbanpenguin.com/using-a-simple-c-program-to-explain-the-suid-permission/"},{default:t(()=>[...s[4]||(s[4]=[a("好的例子",-1)])]),_:1}),s[8]||(s[8]=a("是 ",-1)),s[9]||(s[9]=i("code",null,"passwd",-1)),s[10]||(s[10]=a(" 命令。它需要设置 ",-1)),s[11]||(s[11]=i("code",null,"suid",-1)),s[12]||(s[12]=a(" 位，以便更改密码的操作具有 root 权限。",-1))]),s[30]||(s[30]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /bin/passwd</span></span>
<span class="line"><span>-rwsr-xr-x. 1 root root 27832 Jun 10  2014 /bin/passwd</span></span></code></pre></div><p>设置 <code>suid</code> 位的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod u+s /bin/foo_file_name</span></span></code></pre></div><h4 id="设置组-id-sgid" tabindex="-1">设置组 ID（sgid） <a class="header-anchor" href="#设置组-id-sgid" aria-label="Permalink to “设置组 ID（sgid）”">​</a></h4><p><code>sgid</code> 位与 <code>suid</code> 位类似，操作是在目录的组所有权下完成的，而不是以运行命令的用户身份。</p><p>一个使用 <code>sgid</code> 的例子是，如果多个用户正在同一个目录中工作，并且目录中创建的每个文件都需要具有相同的组权限。下面的示例创建一个名为 <code>collab_dir</code> 的目录，设置 <code>sgid</code> 位，并将组所有权更改为 <code>webdev</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir collab_dir</span></span>
<span class="line"><span>$ chmod g+s collab_dir</span></span>
<span class="line"><span>$ chown :webdev collab_dir</span></span></code></pre></div><p>现在，在该目录中创建的任何文件都将具有 <code>webdev</code> 的组所有权，而不是创建该文件的用户的组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd collab_dir</span></span>
<span class="line"><span>$ touch file-sgid</span></span>
<span class="line"><span>$ ls -lah file-sgid</span></span>
<span class="line"><span>-rw-r--r--. 1 root webdev 0 Jun 12 06:04 file-sgid</span></span></code></pre></div><h4 id="粘滞-位" tabindex="-1">“粘滞”位 <a class="header-anchor" href="#粘滞-位" aria-label="Permalink to ““粘滞”位”">​</a></h4><p>粘滞位表示，只有文件所有者才能删除该文件，即使组权限允许该文件可以删除。通常，在 <code>/tmp</code> 这样的通用或协作目录上，此设置最有意义。在下面的示例中，“所有其他人”权限集的“执行”列中的 <code>t</code> 表示已应用粘滞位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /tmp</span></span>
<span class="line"><span>drwxrwxrwt. 8 root root 4096 Jun 12 06:07 /tmp/</span></span></code></pre></div><p>请记住，这不会阻止某个人编辑该文件，它只是阻止他们删除该目录的内容（LCTT 译注：即删除目录下文件）。</p><p>我们将粘滞位设置为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod o+t foo_dir</span></span></code></pre></div><p>你可以自己尝试在目录上设置粘滞位并赋予其完整的组权限，以便多个属于同一组的用户可以在目录上进行读取、写入和执行。</p><p>接着，以每个用户的身份创建文件，然后尝试以另一个用户的身份删除它们。</p><p>如果一切配置正确，则一个用户应该不能从另一用户那里删除文件。</p><p>请注意，这些位中的每个位也可以用八进制格式设置：SUID = 4、SGID = 2 和 粘滞位 = 1。（LCTT 译注：这里是四位八进制数字）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 4744</span></span>
<span class="line"><span>$ chmod 2644</span></span>
<span class="line"><span>$ chmod 1755</span></span></code></pre></div><h4 id="大写还是小写" tabindex="-1">大写还是小写？ <a class="header-anchor" href="#大写还是小写" aria-label="Permalink to “大写还是小写？”">​</a></h4><p>如果要设置特殊位时看到大写的 <code>S</code> 或 <code>T</code> 而不是小写的字符（如我们之前所见），那是因为不存在（对应的）底层的执行位。为了说明这一点，下面的示例创建一个设置了粘滞位的文件。然后，我们可以添加和删除执行位以演示大小写更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch file cap-ST-demo</span></span>
<span class="line"><span>$ chmod 1755 cap-ST-demo</span></span>
<span class="line"><span>$ ls -l cap-ST-demo</span></span>
<span class="line"><span>-rwxr-xr-t. 1 root root 0 Jun 12 06:16 cap-ST-demo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ chmod o-x cap-X-demo</span></span>
<span class="line"><span>$ ls -l cap-X-demo</span></span>
<span class="line"><span>-rwxr-xr-T. 1 root root 0 Jun 12 06:16 cap-ST-demo</span></span></code></pre></div><h4 id="有条件地设置执行位" tabindex="-1">有条件地设置执行位 <a class="header-anchor" href="#有条件地设置执行位" aria-label="Permalink to “有条件地设置执行位”">​</a></h4><p>至此，我们使用小写的 <code>x</code> 设置了执行位，而无需询问任何问题即可对其进行设置。我们还有另一种选择：使用大写的 <code>X</code> 而不是小写的，它将仅在权限组中某个位置已经有执行位时才设置执行位。这可能是一个很难解释的概念，但是下面的演示将帮助说明它。请注意，在尝试将执行位添加到组特权之后，该位没有被设置上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span>
<span class="line"><span>$ chmod g+X cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span></code></pre></div><p>在这个类似的例子中，我们首先使用小写的 <code>x</code> 将执行位添加到组权限，然后使用大写的 <code>X</code> 为所有其他用户添加权限。这次，大写的 <code>X</code>设置了该权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span>
<span class="line"><span>$ chmod g+x cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r-xr--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span>
<span class="line"><span>$ chmod o+X cap-X-file</span></span>
<span class="line"><span>ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r-xr-x. 1 root root 0 Jun 12 06:31 cap-X-file</span></span></code></pre></div><h3 id="理解-umask" tabindex="-1">理解 umask <a class="header-anchor" href="#理解-umask" aria-label="Permalink to “理解 umask”">​</a></h3><p><code>umask</code> 会屏蔽（或“阻止”）默认权限集中的位，以定义文件或目录的权限。例如，<code>umask</code>输出中的 <code>2</code> 表示它至少在默认情况下阻止了文件的“写入”位。</p><p>使用不带任何参数的 <code>umask</code> 命令可以使我们看到当前的 <code>umask</code> 设置。共有四列：第一列为特殊的<code>suid</code>、<code>sgid</code> 或粘滞位而保留，其余三列代表属主、组和其他人的权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask</span></span>
<span class="line"><span>0022</span></span></code></pre></div><p>为了理解这意味着什么，我们可以用 <code>-S</code> 标志来执行 <code>umask</code>（如下所示）以解释屏蔽位的结果。例如，由于第三列中的值为 <code>2</code>，因此将“写入”位从组和其他部分中屏蔽掉了；只能为它们分配“读取”和“执行”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask -S</span></span>
<span class="line"><span>u=rwx,g=rx,o=rx</span></span></code></pre></div><p>要查看文件和目录的默认权限集是什么，让我们将 <code>umask</code> 设置为全零。这意味着我们在创建文件时不会掩盖任何位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask 000</span></span>
<span class="line"><span>$ umask -S</span></span>
<span class="line"><span>u=rwx,g=rwx,o=rwx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ touch file-umask-000</span></span>
<span class="line"><span>$ ls -l file-umask-000</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root 0 Jul 17 22:03 file-umask-000</span></span></code></pre></div><p>现在，当我们创建文件时，我们看到所有部分的默认权限分别为“读取”（<code>4</code>）和“写入”（<code>2</code>），相当于八进制表示 <code>666</code>。</p><p>我们可以对目录执行相同的操作，并看到其默认权限为 <code>777</code>。我们需要在目录上使用“执行”位，以便可以遍历它们。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir dir-umask-000</span></span>
<span class="line"><span>$ ls -ld dir-umask-000</span></span>
<span class="line"><span>drwxrwxrwx. 2 root root 4096 Jul 17 22:03 dir-umask-000/</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>管理员还有许多其他方法可以控制对系统文件的访问。这些权限是 Linux 的基本权限，我们可以在这些基础上进行构建。如果你的工作为你引入了 FACL 或 SELinux，你会发现它们也建立在这些文件访问的首要规则之上。</p><hr>`,42)),i("p",null,[s[14]||(s[14]=a("via: ",-1)),n(e,{href:"https://opensource.com/article/19/8/linux-permissions-101"},{default:t(()=>[...s[13]||(s[13]=[a("https://opensource.com/article/19/8/linux-permissions-101",-1)])]),_:1})]),i("p",null,[s[19]||(s[19]=a("作者：",-1)),n(e,{href:"https://opensource.com/users/mralexjuarezhttps://opensource.com/users/marcobravohttps://opensource.com/users/greg-p"},{default:t(()=>[...s[15]||(s[15]=[a("Alex Juarez",-1)])]),_:1}),s[20]||(s[20]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[a("lujun9972",-1)])]),_:1}),s[21]||(s[21]=a(" 译者：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1}),s[22]||(s[22]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[a("LCTT",-1)])]),_:1}),s[26]||(s[26]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[a("Linux中国",-1)])]),_:1}),s[27]||(s[27]=a(" 荣誉推出",-1))])])}const y=l(c,[["render",h]]);export{w as __pageData,y as default};
